class Solution {
  private static final long MOD = 1_000_000_007L;

  // number of selections with gain >= g
  private static long countAtLeast(int[] value, int[] decay, long g) {
    long total = 0;
    for (int i = 0; i < value.length; i++)
      if (value[i] >= g) total += (value[i] - g) / decay[i] + 1;
    return total;
  }

  // sum of gains >= g, modulo MOD
  private static long sumAtLeast(int[] value, int[] decay, long g) {
    long total = 0;
    for (int i = 0; i < value.length; i++) {
      if (value[i] < g) continue;
      long k = (value[i] - g) / decay[i] + 1;
      long first = k % MOD * (value[i] % MOD) % MOD;
      long tri = (k * (k - 1) / 2) % MOD * (decay[i] % MOD) % MOD;
      total = (total + first - tri + MOD) % MOD;
    }
    return total;
  }

  public int maxTotalValue(int[] value, int[] decay, int m) {
    if (countAtLeast(value, decay, 1) <= m) return (int) sumAtLeast(value, decay, 1);
    long lo = 1, hi = 1_000_000_000L;
    while (lo < hi) {
      long mid = (lo + hi + 1) >>> 1;
      if (countAtLeast(value, decay, mid) >= m) lo = mid;
      else hi = mid - 1;
    }
    long above = countAtLeast(value, decay, lo + 1);
    long total = (sumAtLeast(value, decay, lo + 1) + (m - above) % MOD * (lo % MOD)) % MOD;
    return (int) total;
  }
}
